/** The policy base premium: every insured item's base premium, summed. */
const policyBasePremiumOf = (items: Item[]): number =>
  items.reduce((total, item) => total + basePremiumOf(item), 0);

const quotePremium = (items: Item[]): number => {
  const policyBase = toSubunits(policyBasePremiumOf(items));

  return toPremiumGold(applyRate(policyBase, FIRST_INSURANCE_SURCHARGE) + toSubunits(PROCESSING_FEE));
};
